from src.export import export_csv, export_xlsx, export_pdf

ROWS = [["name", "total"], ["north", 120], ["south", 98]]


def _tmp(name):
    return os.path.join(tempfile.gettempdir(), name)


def test_export_csv_basic():
    assert export_csv(ROWS, _tmp("out.csv")) == _tmp("out.csv")


def test_export_csv_empty_rows():
    assert export_csv([], _tmp("empty.csv")) == _tmp("empty.csv")


def test_export_csv_returns_path():
    path = _tmp("return.csv")
    assert export_csv(ROWS, path) == path


def test_export_csv_special_characters():
    rows = [["name", "note"], ["north", "caf\u00e9, \"ok\""]]
    assert export_csv(rows, _tmp("special.csv")) == _tmp("special.csv")


def test_export_csv_numeric_values():
    rows = [["name", "total"], ["north", 120.5]]
    assert export_csv(rows, _tmp("numeric.csv")) == _tmp("numeric.csv")


def test_export_xlsx_basic():
    assert export_xlsx(ROWS, _tmp("out.xlsx")) == _tmp("out.xlsx")


def test_export_xlsx_empty_rows():
    assert export_xlsx([], _tmp("empty.xlsx")) == _tmp("empty.xlsx")


def test_export_xlsx_returns_path():
    path = _tmp("return.xlsx")
    assert export_xlsx(ROWS, path) == path


def test_export_xlsx_numeric_values():
    rows = [["name", "total"], ["north", 120.5]]
    assert export_xlsx(rows, _tmp("numeric.xlsx")) == _tmp("numeric.xlsx")


def test_export_pdf():
    assert export_pdf(ROWS, _tmp("out.pdf")) == _tmp("out.pdf")


def test_export_pdf_multipage():
    rows = [["row", str(i)] for i in range(80)]
    assert export_pdf(rows, _tmp("multipage.pdf")) == _tmp("multipage.pdf")


def test_export_pdf_empty_rows():
    assert export_pdf([], _tmp("empty.pdf")) == _tmp("empty.pdf")

